def transform(grid):
    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    background = max(counts, key=counts.get)
    foreground = max((v for v in counts if v != background), key=counts.get)
    return [[v if v == foreground or v == background else background for v in row] for row in grid]

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    keep = set()
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if len(component) >= 3:
                keep.update(component)
    return [[grid[r][c] if (r,c) in keep or grid[r][c] == background else background for c in range(w)] for r in range(h)]

